sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          //get current time
		  var rightNow = new GlideDateTime();
		  // Construct a GlideRecord query to find all NeedIt Task records with Due date
		// field values in the past for the same Assigned to.  The records cannot be in the
		// Closed state.
		  var overdueRecords = new GlideRecord('x_58872_needit_needit_task');

		  overdueRecords.addQuery('due_date', '<=', rightNow); //before today
		  overdueRecords.addQuery('state', '<', 3); //not in closed
		  overdueRecords.addQuery('assigned_to',current.assigned_to); //same assigned to

		  overdueRecords.query(); //execute 


		// Print to the Message field on a notification if theres more than one
		if (overdueRecords.getRowCount() > 1)
		{
		   template.print("In addition to this overdue NeedIt Task, you have " + (overdueRecords.getRowCount() - 1) + " more overdue NeedIt Tasks.");
		}





})(current, template, email, email_action, event);
